3	/**
4	 * Creates a seeded WordPress attachment that Imagify considers optimised but
5	 * missing its next-gen (WebP) version.  This makes the
6	 * "Generate missing next-gen images versions" button appear on the settings
7	 * page and guarantees at least one attachment exists in the media library.
8	 *
9	 * Idempotent: if the seed attachment already exists it is reused.
10	 * Returns the attachment post ID.
11	 *
12	 * Implementation notes
13	 * --------------------
14	 * The PHP code uses double-quoted strings throughout so it can be safely
15	 * passed to `wp eval '...'` (single-quoted shell strings forbid inner
16	 * single quotes).
17	 *
18	 * The SQL query that drives the button visibility requires:
19	 *   1. attachment post with a non-webp mime type
20	 *   2. _imagify_status = "success" | "already_optimized"
21	 *   3. _imagify_data NOT containing `@imagify-webp";a:4:{s:7:"success";b:1;`
22	 *   4. physical backup file at get_imagify_attachment_backup_path()
23	 */
24	export function seedOptimizedImage(): number {
25		const php = `
26	$title = "Imagify E2E Test Seed";
27	$existing = get_posts([
28	    "post_type"   => "attachment",
29	    "title"       => $title,
30	    "numberposts" => 1,
31	    "fields"      => "ids",
32	    "post_status" => "any",
33	]);
34	if ( $existing ) { echo $existing[0]; return; }
35	
36	$gd = imagecreatetruecolor( 100, 100 );
37	$white = imagecolorallocate( $gd, 255, 255, 255 );
38	imagefill( $gd, 0, 0, $white );
39	$upload    = wp_upload_dir();
40	$file_path = $upload["path"] . "/imagify-e2e-seed.jpg";
41	imagejpeg( $gd, $file_path, 90 );
42	imagedestroy( $gd );
43	
44	$id = wp_insert_attachment([
45	    "post_mime_type" => "image/jpeg",
46	    "post_title"     => $title,
47	    "post_content"   => "",
48	    "post_status"    => "inherit",
49	], $file_path );
50	
51	require_once ABSPATH . "wp-admin/includes/image.php";
52	$meta = wp_generate_attachment_metadata( $id, $file_path );
53	wp_update_attachment_metadata( $id, $meta );
54	
55	update_post_meta( $id, "_imagify_status", "success" );
56	update_post_meta( $id, "_imagify_data", [
57	    "sizes" => [
58	        "full" => [
59	            "success"        => true,
60	            "original_size"  => 8000,
61	            "optimized_size" => 6000,
62	            "percent"        => 25.0,
63	        ],
64	    ],
65	    "stats" => [
66	        "original_size"  => 8000,
67	        "optimized_size" => 6000,
68	        "percent"        => 25.0,
69	    ],
70	]);
71	
72	$backup = get_imagify_attachment_backup_path( $file_path );
73	if ( $backup ) {
74	    wp_mkdir_p( dirname( $backup ) );
75	    copy( $file_path, $backup );
76	}
77	
78	delete_transient( "imagify_stat_without_next_gen" );
79	echo $id;
80	`;
81	
82		const result = wpCli( `eval '${ php }'` );
83		return parseInt( result.trim(), 10 );
84	}
